export function getRagGuide(lessonId) {
  const lesson = lessons[Number(lessonId)];
  if (!lesson) return undefined;
  const [prompt, correct, wrongA, wrongB, why] = lesson.check;
  const answers = [correct, wrongA, wrongB];
  const answerOrder = Number(lessonId) % 3;
  const options = [answers[answerOrder], answers[(answerOrder + 1) % 3], answers[(answerOrder + 2) % 3]];
  // Teaching content and interactive mechanism views are bespoke per RAG topic.
  // Both views are diagrams of causal/conceptual stages, not actual retrieval logs.
  return {
    question: `What is ${lesson.terms[0][0].toLowerCase()} in this RAG design, and why does it matter?`,
    mechanism:lesson.flow.map(([name,explanation])=>`${name}: ${explanation}`).join(' '),
    plain: lesson.plain,
    goals:[`Explain ${lesson.terms[0][0].toLowerCase()} and the core concept in plain language.`,`Trace ${lesson.flow[1][0].toLowerCase()} through the system and identify its important data boundary.`,`Diagnose the illustrated failure and test a production mitigation.`],
    concepts: lesson.terms,
    views:[
      {name:'How it works',note:'Select each stage to trace the illustrated RAG mechanism. This is not a real index or model execution.',steps:lesson.flow},
      {name:'Where it fails',note:'Inspect a failure sequence and the diagnostic or recovery decision. No accuracy is simulated.',steps:lesson.counter}
    ],
    example:{title:'Work through a real system constraint',steps:lesson.case,takeaway:lesson.takeaway},
    precision:lesson.precision,
    engineering:lesson.engineering,
    interview:lesson.interview,
    checkpoint:{question:prompt,options,correct:options.indexOf(correct),why},
    resources:reading[Number(lessonId)] ?? []
  };
}
export const RAG_GUIDE_COUNT = Object.keys(lessons).length;
